import numpy as np
def load(n):
    d=np.load(n+'.npz',allow_pickle=True); return {k:d[k] for k in d.files}
A,B=load('A'),load('B'); r=lambda z:np.maximum(z,0)
br=np.load('bridge.npz'); M,c=br['M'],br['c']
print(M.shape,c.shape,M.dtype,np.isfinite(M).all(),np.isfinite(c).all())
def sm(L): L=L-L.max(1,keepdims=True); e=np.exp(L); return e/e.sum(1,keepdims=True)
Bf=lambda z:r(r(z)@B['W1']+B['b1'])@B['W2']+B['b2']
for f in ['syn.npz','synR.npz']:
    X=np.load(f)['X'][2400:]
    LB=Bf(X@B['W0']+B['b0']); pB=LB.argmax(1); conf=sm(LB).max(1)
    pr=Bf(r(X@A['W0']+A['b0'])@M+c).argmax(1)
    for t in [0,.5,.8,.95]:
        s=conf>=t; print(f,'conf>=',t,'n',s.sum(),'agree',(pr[s]==pB[s]).mean().round(3))
